import { Injectable } from '@nestjs/common';
import { exec } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';

@Injectable()
export class AppService {
  async createGif(files: Express.Multer.File[], targetSize: string, delay: number, appendReverted: boolean): Promise<Buffer> {
    const tempDir = './temp';
    if (!fs.existsSync(tempDir)) {
      fs.mkdirSync(tempDir);
    }

    const filePaths = files.map(file => file.path);
    const outputGifPath = path.join(tempDir, `output-${Date.now()}.gif`);

    let command = `convert -delay ${delay} -resize ${targetSize} ${filePaths.join(' ')} `;

    if (appendReverted) {
      command += `${filePaths.reverse().join(' ')} `;
    }

    command += outputGifPath;

    return new Promise((resolve, reject) => {
      exec(command, (error) => {
        if (error) {
          reject(error);
        } else {
          fs.readFile(outputGifPath, (err, data) => {
            if (err) {
              reject(err);
            } else {
              resolve(data);
              fs.unlinkSync(outputGifPath);
              filePaths.forEach(filePath => fs.unlinkSync(filePath));
            }
          });
        }
      });
    });
  }
}
